{"query":"SELECT COUNT(*) AS overlap_liver_kidney FROM (
SELECT Gene FROM proteinatlas WHERE "RNA tissue specificity"='Tissue enriched' AND "RNA tissue specific nTPM" LIKE '%liver:%'
INTERSECT
SELECT Gene FROM proteinatlas WHERE "RNA tissue specificity"='Tissue enriched' AND "RNA tissue specific nTPM" LIKE '%kidney:%'
)"}
